// Des: Tests the site map: seeds, links, caps, halts, redaction
// Flo: fake pages > map > files in <stat>/map/<date>/ > assert pages, controls, caps, deny list, halts; nothing is clicked
// I/O: real local Chrome (skipped when absent) + mock site > pass or fail (no leaks)
// Run: zig build test -Dfile=ru-map-crwl-test.zig
// ===================================================================
const std = @import("std"); const rigz = @import("te-rigz-brow.zig"); const crwl = @import("ru-map-crwl.zig"); const task = @import("ru-task-runn.zig"); const cfgz = @import("cf-conf-load.zig");
fn ctxOf(rig: *rigz.Rig) !task.Ctx { rig.conf.noti_chai_orde = &.{"file"}; var cx = rig.ctx(.read); cx.statd = try rig.absOf("stat"); return cx; }
fn readAll(rig: *rigz.Rig, cx: *task.Ctx, rel: []const u8) ![]u8 { const day = try crwl.dayStr(cx.aren, task.nowMs(cx)); const fp = try std.fs.path.join(cx.aren, &.{ cx.statd, "map", day, rel }); return std.Io.Dir.cwd().readFileAlloc(rig.iozz, fp, cx.aren, .limited(1 << 20)); }
test "map follows allowed links, writes one file per page and an index, and never clicks" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); rig.conf.map_seed_list = &.{"/messages/"}; var cx = try ctxOf(&rig); const cnt = try crwl.mapRun(&cx); try std.testing.expectEqual(@as(u32, 3), cnt); const idx = try readAll(&rig, &cx, "index.json"); try std.testing.expect(std.mem.find(u8, idx, "/messages/t/42") != null); const first = try readAll(&rig, &cx, "001-messages_.json"); try std.testing.expect(std.mem.find(u8, first, "Unread conversation with Ann") != null); try std.testing.expectEqual(@as(usize, 0), rig.mock.recCnt()); }
test "map respects the page cap, the depth cap and the help cap" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); rig.conf.map_seed_list = &.{"/messages/"}; rig.conf.map_page_maxx = 1; var cx = try ctxOf(&rig); try std.testing.expectEqual(@as(u32, 1), try crwl.mapRun(&cx)); rig.conf.map_page_maxx = 25; rig.conf.map_deep_maxx = 0; var c2 = try ctxOf(&rig); try std.testing.expectEqual(@as(u32, 1), try crwl.mapRun(&c2)); rig.conf.map_deep_maxx = 2; rig.conf.capz_help_dayz = 3; var c3 = try ctxOf(&rig); try std.testing.expectEqual(@as(u32, 1), try crwl.mapRun(&c3)); }
test "paths on the deny list or outside the allowed list are never visited" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); rig.conf.map_seed_list = &.{ "/logout", "/x/delete/1", "/elsewhere/" }; var cx = try ctxOf(&rig); try std.testing.expectEqual(@as(u32, 0), try crwl.mapRun(&cx)); try std.testing.expect(!crwl.allowed(rig.conf, "/logout")); try std.testing.expect(!crwl.allowed(rig.conf, "/settings/delete_account")); try std.testing.expect(!crwl.allowed(rig.conf, "https://evil.test/settings")); try std.testing.expect(crwl.allowed(rig.conf, "/settings/privacy")); try std.testing.expect(crwl.allowed(rig.conf, "/accountscenter/password_and_security")); }
test "a security check stops the map with Halted and nothing is mapped" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); rig.conf.map_seed_list = &.{"/checkpoint"}; rig.conf.map_allo_list = &.{"/checkpoint"}; var cx = try ctxOf(&rig); try std.testing.expectError(error.Halted, crwl.mapRun(&cx)); }
test "controls are the real accessibility names of the page: settings page lists its buttons, boxes and toggles" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); rig.conf.map_seed_list = &.{"/settings/privacy"}; var cx = try ctxOf(&rig); try std.testing.expectEqual(@as(u32, 1), try crwl.mapRun(&cx)); const pg = try readAll(&rig, &cx, "001-settings_privacy.json"); try std.testing.expect(std.mem.find(u8, pg, "Default audience") != null); try std.testing.expect(std.mem.find(u8, pg, "Save changes") != null); try std.testing.expect(std.mem.find(u8, pg, "Search engines can link to your profile") != null); }
test "dayStr gives the UTC date" { var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); try std.testing.expectEqualStrings("1970-01-01", try crwl.dayStr(aren.allocator(), 0)); try std.testing.expectEqualStrings("1971-01-01", try crwl.dayStr(aren.allocator(), 365 * 86400000)); try std.testing.expectEqualStrings("2024-02-29", try crwl.dayStr(aren.allocator(), 1709164800000)); }
